BEGIN;
DO $$ DECLARE actor uuid;s uuid;s2 uuid;a uuid;b uuid;doc jsonb;first jsonb;r jsonb;review uuid;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-merge-recovery@example.test','fictional-proof','admin',true)RETURNING id INTO actor;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(actor,repeat('1',64))RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(actor,repeat('2',64))RETURNING id INTO s2;
 INSERT INTO public.members(name,email)VALUES('Fictional duplicate','fictional-merge-source@example.test')RETURNING id INTO a;
 INSERT INTO public.members(name,email)VALUES('Fictional canonical','fictional-merge-target@example.test')RETURNING id INTO b;
 doc:=jsonb_build_object('sourceId',a,'targetId',b,'sourceRevision',1,'targetRevision',1);
 r:=public.inspect_member_merge_write(actor,s,'preview',doc,repeat('3',64),repeat('4',64),repeat('5',64));IF(r->>'committed')::boolean OR NOT(r->>'canRetry')::boolean THEN RAISE EXCEPTION 'Unaccepted merge review inspection incorrect';END IF;
 first:=public.mutate_member_merge_write(actor,s,'preview',doc,repeat('3',64),NULL,repeat('4',64),repeat('5',64),NULL);review:=(first->>'reviewId')::uuid;
 r:=public.mutate_member_merge_write(actor,s,'preview',doc,repeat('3',64),NULL,repeat('4',64),repeat('5',64),NULL);IF r<>first OR(SELECT count(*) FROM gdg_security.member_merge_reviews WHERE actor_id=actor)<>1 THEN RAISE EXCEPTION 'Merge review replay duplicated';END IF;
 r:=public.inspect_member_merge_write(actor,s,'preview',doc,repeat('3',64),repeat('4',64),repeat('5',64));IF r->'receipt'<>first OR NOT(r->>'committed')::boolean THEN RAISE EXCEPTION 'Accepted review inspection failed';END IF;
 IF EXISTS(SELECT 1 FROM public.idempotency_keys WHERE scope='member-merge:'||actor||':'||s||':preview' AND(result::text LIKE '%Fictional%' OR result::text LIKE '%@%' OR result::text LIKE '%token%')) THEN RAISE EXCEPTION 'Private merge data cached in receipt';END IF;
 doc:=jsonb_build_object('reviewId',review,'sourceConfirmation','MEM-'||upper(replace(a::text,'-','')),'targetConfirmation','MEM-'||upper(replace(b::text,'-','')));
 BEGIN PERFORM public.mutate_member_merge_write(actor,s,'commit',doc,repeat('3',64),NULL,repeat('6',64),repeat('7',64),NULL);RAISE EXCEPTION 'Merge bypassed current proof';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 first:=public.mutate_member_merge_write(actor,s,'commit',doc,repeat('3',64),'fictional-proof',repeat('6',64),repeat('7',64),NULL);
 r:=public.mutate_member_merge_write(actor,s,'commit',doc,repeat('3',64),NULL,repeat('6',64),repeat('7',64),NULL);IF r<>first OR(SELECT revision FROM public.members WHERE id=a)<>2 OR(SELECT revision FROM public.members WHERE id=b)<>2 THEN RAISE EXCEPTION 'Accepted merge duplicated or required retained proof';END IF;
 UPDATE public.members SET revision=revision+1,name='Fictional later canonical' WHERE id=b;
 r:=public.mutate_member_merge_write(actor,s,'commit',doc,repeat('3',64),NULL,repeat('6',64),repeat('7',64),NULL);IF r<>first OR(SELECT name FROM public.members WHERE id=b)<>'Fictional later canonical' THEN RAISE EXCEPTION 'Old merge replay changed later canonical';END IF;
 r:=public.inspect_member_merge_write(actor,s,'commit',doc,repeat('3',64),repeat('6',64),repeat('7',64));IF NOT(r->>'committed')::boolean OR(r->>'canRetry')::boolean OR r->'receipt'<>first THEN RAISE EXCEPTION 'Accepted merge receipt inspection failed';END IF;
 BEGIN PERFORM public.inspect_member_merge_write(actor,s2,'commit',doc,repeat('3',64),repeat('6',64),repeat('7',64));RAISE EXCEPTION 'Merge review crossed sessions';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 BEGIN PERFORM public.inspect_member_merge_write(actor,s,'commit',doc,repeat('3',64),repeat('6',64),repeat('8',64));RAISE EXCEPTION 'Merge receipt changed body';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 UPDATE public.admin_users SET role='team_member' WHERE id=actor;
 BEGIN PERFORM public.inspect_member_merge_write(actor,s,'commit',doc,repeat('3',64),repeat('6',64),repeat('8',64));RAISE EXCEPTION 'Merge authority checked after body hash';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.admin_users SET role='admin' WHERE id=actor;UPDATE public.idempotency_keys SET expires_at=now()-interval '1 second' WHERE scope='member-merge:'||actor||':'||s||':commit';
 BEGIN PERFORM public.inspect_member_merge_write(actor,s,'commit',doc,repeat('3',64),repeat('6',64),repeat('7',64));RAISE EXCEPTION 'Expired merge receipt disclosed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 IF has_function_privilege('anon','public.inspect_member_merge_write(uuid,uuid,text,jsonb,text,text,text)','EXECUTE') OR has_function_privilege('authenticated','public.mutate_member_merge_write(uuid,uuid,text,jsonb,text,text,text,text,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.inspect_member_merge_write(uuid,uuid,text,jsonb,text,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Merge recovery grants incorrect';END IF;
END $$;
ROLLBACK;
